package main

import (
 "context"
 "net/http"
 "sort"
 "sync"
 "time"
)
var matchingMu sync.Mutex
func matchingLoop() {ticker:=time.NewTicker(10*time.Millisecond);defer ticker.Stop();for range ticker.C {runMatching(context.Background())}}
func internalGetMatching(w http.ResponseWriter,r *http.Request) {runMatching(r.Context());w.WriteHeader(204)}
func runMatching(ctx context.Context) {
 if !matchingMu.TryLock() {return};defer matchingMu.Unlock()
 state.RLock()
 rides:=[]Ride{};for _,cr:=range state.rides {if !cr.Ride.ChairID.Valid {rides=append(rides,cr.Ride)}}
 type availableChair struct {ID string;Latitude,Longitude,Speed int}
 chairs:=[]availableChair{}
 if len(rides)>0 {for id,c:=range state.chairs {if !c.IsActive || !chairAvailableLocked(id,true) {continue};l,ok:=state.locations[id];if !ok {continue};speed:=state.speeds[c.Model];if speed<1 {speed=1};chairs=append(chairs,availableChair{id,l.Latitude,l.Longitude,speed})}}
 state.RUnlock()
 sort.Slice(rides,func(i,j int)bool{return rides[i].CreatedAt.Before(rides[j].CreatedAt)})
 for _,ride:=range rides {
  best:=-1;cost:=1e30
  for i,c:=range chairs {if c.ID=="" {continue};x:=float64(calculateDistance(c.Latitude,c.Longitude,ride.PickupLatitude,ride.PickupLongitude))/float64(c.Speed);if x<cost {best=i;cost=x}}
  if best<0 {break}
  if _,err:=db.ExecContext(ctx,`UPDATE rides SET chair_id=? WHERE id=? AND chair_id IS NULL`,chairs[best].ID,ride.ID);err!=nil {return}
  notifyRide(ride.ID);chairs[best].ID=""
 }
}
