package main

import (
 "container/heap"
 "context"
 "database/sql"
 "net/http"
 "os"
 "sort"
 "strconv"
 "strings"
 "sync"
 "time"
)
var matchingMu sync.Mutex
func envFloat(key string,def float64) float64 {v,e:=strconv.ParseFloat(os.Getenv(key),64);if e!=nil{return def};return v}
var tripWeight=envFloat("ISUCON_MATCH_TRIP_WEIGHT",0.15)
var ageWeight=envFloat("ISUCON_MATCH_AGE_WEIGHT",0.5)
var urgentAfter=envFloat("ISUCON_MATCH_URGENT_AFTER",3)
var maxPickup=envFloat("ISUCON_MATCH_MAX_PICKUP",200)
var matchInterval=envFloat("ISUCON_MATCH_INTERVAL_MS",10)
func matchingLoop() {ticker:=time.NewTicker(time.Duration(matchInterval)*time.Millisecond);defer ticker.Stop();for range ticker.C {runMatching(context.Background())}}
func internalGetMatching(w http.ResponseWriter,r *http.Request) {runMatching(r.Context());w.WriteHeader(204)}
type matchingChair struct {ID string;Latitude,Longitude,Speed int}
type matchingPair struct {ride,chair int;cost float64}
type pairHeap []matchingPair
func(h pairHeap)Len()int{return len(h)}
func(h pairHeap)Less(i,j int)bool{return h[i].cost<h[j].cost}
func(h pairHeap)Swap(i,j int){h[i],h[j]=h[j],h[i]}
func(h *pairHeap)Push(x interface{}){*h=append(*h,x.(matchingPair))}
func(h *pairHeap)Pop()interface{}{old:=*h;x:=old[len(old)-1];*h=old[:len(old)-1];return x}
func runMatching(ctx context.Context) {
 if !matchingMu.TryLock() {return};defer matchingMu.Unlock()
 state.RLock()
 rides:=[]Ride{};for _,cr:=range state.rides {if !cr.Ride.ChairID.Valid {rides=append(rides,cr.Ride)}}
 chairs:=[]matchingChair{}
 if len(rides)>0 {for id,c:=range state.chairs {if !c.IsActive || !chairAvailableLocked(id,true) {continue};l,ok:=state.locations[id];if !ok {continue};speed:=state.speeds[c.Model];if speed<1 {speed=1};chairs=append(chairs,matchingChair{id,l.Latitude,l.Longitude,speed})}}
 state.RUnlock()
 if len(rides)==0 || len(chairs)==0 {return}
 sort.Slice(rides,func(i,j int)bool{return rides[i].CreatedAt.Before(rides[j].CreatedAt)})
 assigned:=make([]bool,len(rides));used:=make([]bool,len(chairs));pairs:=[]matchingPair{};now:=time.Now().UTC()
 if os.Getenv("ISUCON_MATCHING_MODE")=="fifo" {
  for ri,ride:=range rides {best:=-1;cost:=1e30;for ci,c:=range chairs {if used[ci] {continue};x:=float64(calculateDistance(c.Latitude,c.Longitude,ride.PickupLatitude,ride.PickupLongitude))/float64(c.Speed);if x<cost {best=ci;cost=x}};if best<0{break};pairs=append(pairs,matchingPair{ri,best,cost});used[best]=true;assigned[ri]=true}
 }else{
  // Serve requests close to their deadline first, then minimize fleet travel time.
  for ri,ride:=range rides {if now.Sub(ride.CreatedAt).Seconds()<urgentAfter {break};best:=-1;cost:=1e30;for ci,c:=range chairs {if used[ci]{continue};x:=float64(calculateDistance(c.Latitude,c.Longitude,ride.PickupLatitude,ride.PickupLongitude))/float64(c.Speed);if x<cost{best=ci;cost=x}};if best<0{break};pairs=append(pairs,matchingPair{ri,best,cost});used[best]=true;assigned[ri]=true}
  bestForChair:=func(ci int)matchingPair {c:=chairs[ci];p:=matchingPair{ride:-1,chair:ci,cost:1e30};for ri,r:=range rides {if assigned[ri]{continue};pickup:=calculateDistance(c.Latitude,c.Longitude,r.PickupLatitude,r.PickupLongitude);if float64(pickup)>maxPickup {continue};trip:=calculateDistance(r.PickupLatitude,r.PickupLongitude,r.DestinationLatitude,r.DestinationLongitude);age:=now.Sub(r.CreatedAt).Seconds();cost:=(float64(pickup)+float64(trip)*tripWeight)/float64(c.Speed)/(1+age*ageWeight);if cost<p.cost {p.ride=ri;p.cost=cost}};return p}
  h:=&pairHeap{};for ci:=range chairs {if !used[ci] {p:=bestForChair(ci);if p.ride>=0 {heap.Push(h,p)}}}
  for h.Len()>0 {p:=heap.Pop(h).(matchingPair);if assigned[p.ride] {p=bestForChair(p.chair);if p.ride>=0 {heap.Push(h,p)};continue};assigned[p.ride]=true;used[p.chair]=true;pairs=append(pairs,p)}
 }
 if len(pairs)==0{return}
 query:=strings.Builder{};query.WriteString("UPDATE rides SET chair_id=CASE id ");args:=[]interface{}{}
 for _,p:=range pairs {query.WriteString("WHEN ? THEN ? ");args=append(args,rides[p.ride].ID,chairs[p.chair].ID)}
 query.WriteString("END, updated_at=? WHERE chair_id IS NULL AND id IN (");args=append(args,now)
 for i,p:=range pairs {if i>0 {query.WriteByte(',')};query.WriteByte('?');args=append(args,rides[p.ride].ID)};query.WriteByte(')')
 if _,err:=db.ExecContext(ctx,query.String(),args...);err!=nil{return}
 state.Lock()
 for _,p:=range pairs {rid,cid:=rides[p.ride].ID,chairs[p.chair].ID;cr:=state.rides[rid];if cr==nil || cr.Ride.ChairID.Valid {continue};cr.Ride.ChairID=sql.NullString{String:cid,Valid:true};cr.Ride.UpdatedAt=now;state.chairRides[cid]=append(state.chairRides[cid],rid)}
 state.Unlock()
 for _,p:=range pairs {notifications.publish("u"+rides[p.ride].UserID);notifications.publish("c"+chairs[p.chair].ID)}
}
